import { useState, useRef, useEffect } from 'react';
import { Bold, Italic, Underline, List, ListOrdered, AlignLeft, AlignCenter, AlignRight, Link, Image as ImageIcon, Heading1, Heading2, Heading3, Undo, Redo, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from 'sonner';
import type { I18nText } from '@/lib/i18n-text';
import { createI18nText } from '@/lib/i18n-text';
import { useI18n } from '@/i18n/I18nContext';
import { compressImage } from '@/utils/compress-image';
import { imgPath } from '@/utils/img-path';
import { resolveAssetUrl } from '@/utils/basename';

interface RichTextEditorProps {
  value: I18nText;
  onChange: (val: I18nText) => void;
  placeholder?: string;
  height?: string;
  maxHeight?: string;
}


const LANGUAGES: { code: 'en' | 'zh' | 'es' | 'ja'; label: string }[] = [
  { code: 'en', label: 'EN' },
  { code: 'zh', label: '中' },
  { code: 'es', label: 'ES' },
  { code: 'ja', label: '日' },
];

export default function RichTextEditor({
  value,
  onChange,
  placeholder = '',
  height = '320px',
  maxHeight,
}: RichTextEditorProps) {
  const { adminLanguage } = useI18n();
  const [activeLang, setActiveLang] = useState<'en' | 'zh' | 'es' | 'ja'>(
    (adminLanguage as 'en' | 'zh' | 'es' | 'ja') || 'en'
  );
  const [linkDialogOpen, setLinkDialogOpen] = useState(false);
  const [linkUrl, setLinkUrl] = useState('');
  const [imageDialogOpen, setImageDialogOpen] = useState(false);
  const [imageUrl, setImageUrl] = useState('');
  const savedRangeRef = useRef<Range | null>(null);
  const editorRefs = useRef<Record<string, HTMLDivElement | null>>({});
  // 记录上次写入编辑器的内容（字符串形式），用于判断 value 是否真的变了
  // 避免每次父组件 setForm 导致 value 引用变化 → useEffect 重置 innerHTML → 光标丢失
  const lastWrittenRef = useRef<Record<string, string>>({});

  /**
   * 将存储的 HTML 中 /images/... 等本地路径解析为当前环境下可访问的完整 URL
   * 用于编辑器加载时，保证图片能正常显示
   */
  const resolveHtmlImagePaths = (html: string): string => {
    if (!html || !html.includes('<img')) return html;
    return html.replace(
      /(<img[^>]+src=)(["'])([^"']+)(\2[^>]*>)/gi,
      (match, prefix: string, quote: string, src: string, suffix: string) => {
        // 已经是 data: / http(s): / blob: 的不需要处理
        if (
          src.startsWith('data:') ||
          src.startsWith('blob:') ||
          /^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(src)
        ) {
          return match;
        }
        // 妙搭 storage 路径也不需要处理
        if (src.startsWith('/spark/')) return match;
        // 本地 /images/ 或 ./images/ 等路径 → 解析成完整 URL
        if (
          src.startsWith('/images/') ||
          src.startsWith('./images/') ||
          src.startsWith('images/')
        ) {
          return `${prefix}${quote}${imgPath(src)}${suffix}`;
        }
        return match;
      }
    );
  };

  /**
   * 将编辑器 HTML 中的图片路径还原为存储用的原始相对路径
   * - GitHub raw URL → /images/custom/...
   * - 带 basename 的本地路径 → /images/...
   * - base64 / blob 保留
   */
  const normalizeHtmlImagePaths = (html: string): string => {
    if (!html || !html.includes('<img')) return html;

    // 计算当前 basename 下 /images/ 的完整前缀，用于还原
    const resolvedImagesPrefix = resolveAssetUrl('/images/');

    return html.replace(
      /(<img[^>]+src=)(["'])([^"']+)(\2[^>]*>)/gi,
      (match, prefix: string, quote: string, src: string, suffix: string) => {
        if (!src) return match;

        // 1. GitHub raw URL → 还原为 /images/custom/...
        const ghRawMatch = src.match(
          /https:\/\/raw\.githubusercontent\.com\/[^/]+\/[^/]+\/[^/]+\/(images\/custom\/[^"']+)/
        );
        if (ghRawMatch) {
          return `${prefix}${quote}/${ghRawMatch[1]}${suffix}`;
        }

        // 2. 当前环境 /images/ 完整路径 → 还原为 /images/...
        //    处理 resolveAssetUrl 返回的带 basename 路径
        if (resolvedImagesPrefix && src.startsWith(resolvedImagesPrefix)) {
          const relPath = '/images/' + src.slice(resolvedImagesPrefix.length);
          return `${prefix}${quote}${relPath}${suffix}`;
        }

        // 3. 妙搭平台 /spark/app/.../images/... → 提取 /images/ 之后部分
        if (src.includes('/images/') && src.startsWith('/')) {
          const idx = src.indexOf('/images/');
          if (idx >= 0) {
            const relPath = src.slice(idx);
            return `${prefix}${quote}${relPath}${suffix}`;
          }
        }

        return match;
      }
    );
  };

  // 初始化 + value 变化时同步编辑内容（切换文章 / 外部重置时更新）
  // 注意：用 ref 回调也会初始化一次（下方 ref={setEditorRef}），这里主要处理 value 的后续变化
  // 加载时把 /images/... 路径解析为完整 URL，保证图片正常显示
  useEffect(() => {
    LANGUAGES.forEach((lang) => {
      const el = editorRefs.current[lang.code];
      if (!el) return;
      const rawVal = value[lang.code] ?? '';
      const last = lastWrittenRef.current[lang.code] ?? '';
      // 只有真正的值变化（不是同一字符串的引用变化）才重写 innerHTML
      // 否则会导致光标丢失、输入被打断
      if (rawVal !== last) {
        const displayHtml = resolveHtmlImagePaths(rawVal);
        el.innerHTML = displayHtml || '';
        lastWrittenRef.current[lang.code] = rawVal;
      }
    });
  }, [value, resolveHtmlImagePaths]);

  // ref 回调：DOM 挂载时立即写入初始内容，解决 TabsContent/Dialog 动画导致的挂载时序问题
  const setEditorRef = (lang: 'en' | 'zh' | 'es' | 'ja') => (el: HTMLDivElement | null) => {
    editorRefs.current[lang] = el;
    if (el) {
      const rawVal = value[lang] ?? '';
      const last = lastWrittenRef.current[lang] ?? '';
      if (rawVal && rawVal !== last) {
        const displayHtml = resolveHtmlImagePaths(rawVal);
        el.innerHTML = displayHtml;
        lastWrittenRef.current[lang] = rawVal;
      }
    }
  };

  const saveSelection = () => {
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      savedRangeRef.current = sel.getRangeAt(0).cloneRange();
    }
  };

  const restoreSelection = () => {
    const sel = window.getSelection();
    const editor = editorRefs.current[activeLang];
    if (savedRangeRef.current && editor && sel) {
      // 确保保存的 range 仍在当前编辑器内
      if (editor.contains(savedRangeRef.current.startContainer)) {
        sel.removeAllRanges();
        sel.addRange(savedRangeRef.current);
        return true;
      }
    }
    // 没有保存的选区或选区不在编辑器内 → 将光标放到编辑器末尾
    if (editor && sel) {
      editor.focus();
      const range = document.createRange();
      range.selectNodeContents(editor);
      range.collapse(false);
      sel.removeAllRanges();
      sel.addRange(range);
      return true;
    }
    return false;
  };

  const execCommand = (command: string, val: string = '') => {
    document.execCommand(command, false, val);
    // 更新对应语言的内容
    const el = editorRefs.current[activeLang];
    if (el) {
      updateValue(activeLang, el.innerHTML);
    }
  };

  const updateValue = (lang: 'en' | 'zh' | 'es' | 'ja', displayHtml: string) => {
    // 保存时把图片路径还原为存储用的原始相对路径
    const storageHtml = normalizeHtmlImagePaths(displayHtml);
    lastWrittenRef.current[lang] = storageHtml;
    onChange({
      ...value,
      [lang]: storageHtml,
    });
  };

  const handleInput = (lang: 'en' | 'zh' | 'es' | 'ja') => {
    const el = editorRefs.current[lang];
    if (el) {
      updateValue(lang, el.innerHTML);
    }
  };

  const handleLinkInsert = () => {
    if (!linkUrl.trim()) return;
    execCommand('createLink', linkUrl.trim());
    setLinkUrl('');
    setLinkDialogOpen(false);
  };

  const handleImageInsert = () => {
    if (!imageUrl.trim()) return;
    restoreSelection();
    const editor = editorRefs.current[activeLang];
    if (!editor) return;
    editor.focus();
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      const range = sel.getRangeAt(0);
      if (!editor.contains(range.startContainer)) {
        const newRange = document.createRange();
        newRange.selectNodeContents(editor);
        newRange.collapse(false);
        sel.removeAllRanges();
        sel.addRange(newRange);
      }
    }
    const img = document.createElement('img');
    img.src = imageUrl.trim();
    img.style.maxWidth = '100%';
    img.alt = 'inserted image';
    const range = sel && sel.rangeCount > 0 ? sel.getRangeAt(0) : null;
    if (range) {
      range.deleteContents();
      range.insertNode(img);
    } else {
      editor.appendChild(img);
    }
    updateValue(activeLang, editor.innerHTML);
    setImageUrl('');
    setImageDialogOpen(false);
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) {
      toast.error('Image must be less than 5MB');
      return;
    }
    try {
      const compressed = await compressImage(file, 1000, 0.7);
      restoreSelection();
      // 使用 DOM API 插入图片，比 execCommand 更可靠（Dialog 打开时也能工作）
      const editor = editorRefs.current[activeLang];
      if (!editor) return;
      editor.focus();
      const sel = window.getSelection();
      if (sel && sel.rangeCount > 0) {
        const range = sel.getRangeAt(0);
        // 如果选区不在编辑器内，放到编辑器末尾
        if (!editor.contains(range.startContainer)) {
          const newRange = document.createRange();
          newRange.selectNodeContents(editor);
          newRange.collapse(false);
          sel.removeAllRanges();
          sel.addRange(newRange);
        }
      }
      const img = document.createElement('img');
      img.src = compressed;
      img.style.maxWidth = '100%';
      img.alt = 'inserted image';
      const range = sel && sel.rangeCount > 0 ? sel.getRangeAt(0) : null;
      if (range) {
        range.deleteContents();
        range.insertNode(img);
        // 光标移到图片后面
        const newRange = document.createRange();
        newRange.setStartAfter(img);
        newRange.collapse(true);
        sel?.removeAllRanges();
        sel?.addRange(newRange);
      } else {
        editor.appendChild(img);
      }
      updateValue(activeLang, editor.innerHTML);
    } catch (err) {
      toast.error('Failed to process image: ' + (err instanceof Error ? err.message : String(err)));
    }
    e.target.value = '';
  };

  const ToolbarButton = ({ icon: Icon, cmd, arg, title }: { icon: typeof Bold; cmd: string; arg?: string; title: string }) => (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      className="h-7 w-7"
      onMouseDown={(e) => {
        e.preventDefault();
        execCommand(cmd, arg);
      }}
      title={title}
    >
      <Icon className="size-3.5" />
    </Button>
  );

  return (
    <div className="border border-border rounded-md overflow-hidden bg-background">
      {/* Toolbar */}
      <div className="flex flex-wrap items-center gap-0.5 p-2 border-b border-border bg-muted/20">
        <ToolbarButton icon={Undo} cmd="undo" title="Undo" />
        <ToolbarButton icon={Redo} cmd="redo" title="Redo" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={Heading1} cmd="formatBlock" arg="h2" title="Heading 1" />
        <ToolbarButton icon={Heading2} cmd="formatBlock" arg="h3" title="Heading 2" />
        <ToolbarButton icon={Heading3} cmd="formatBlock" arg="h4" title="Heading 3" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={Bold} cmd="bold" title="Bold" />
        <ToolbarButton icon={Italic} cmd="italic" title="Italic" />
        <ToolbarButton icon={Underline} cmd="underline" title="Underline" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={List} cmd="insertUnorderedList" title="Bullet List" />
        <ToolbarButton icon={ListOrdered} cmd="insertOrderedList" title="Numbered List" />
        <div className="w-px h-5 bg-border mx-1" />
        <ToolbarButton icon={AlignLeft} cmd="justifyLeft" title="Align Left" />
        <ToolbarButton icon={AlignCenter} cmd="justifyCenter" title="Align Center" />
        <ToolbarButton icon={AlignRight} cmd="justifyRight" title="Align Right" />
        <div className="w-px h-5 bg-border mx-1" />
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={() => setLinkDialogOpen(true)}
          title="Insert Link"
        >
          <Link className="size-3.5" />
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="h-7 w-7"
          onClick={() => {
            saveSelection();
            setImageDialogOpen(true);
          }}
          title="Insert Image"
        >
          <ImageIcon className="size-3.5" />
        </Button>
      </div>

      {/* Language Tabs */}
      <Tabs value={activeLang} onValueChange={(v) => setActiveLang(v as typeof activeLang)}>
        <TabsList className="w-full justify-start rounded-none border-b border-border bg-transparent h-9 p-0">
          {LANGUAGES.map((lang) => (
            <TabsTrigger
              key={lang.code}
              value={lang.code}
              className="h-9 px-4 text-xs data-[state=active]:bg-background data-[state=active]:shadow-none"
            >
              {lang.label}
            </TabsTrigger>
          ))}
        </TabsList>
        {LANGUAGES.map((lang) => (
          <TabsContent key={lang.code} value={lang.code} className="m-0">
            <div
              ref={setEditorRef(lang.code)}
              contentEditable
              suppressContentEditableWarning
              onInput={() => handleInput(lang.code)}
              onBlur={() => handleInput(lang.code)}
              className="min-h-[320px] p-4 text-sm leading-relaxed focus:outline-none prose prose-sm dark:prose-invert max-w-none prose-headings:font-semibold prose-a:text-primary"
              style={{ minHeight: height, ...(maxHeight ? { maxHeight, overflowY: 'auto' } : {}) }}
              data-placeholder={placeholder}
            />
          </TabsContent>
        ))}
      </Tabs>

      {/* Link Dialog */}
      <Dialog open={linkDialogOpen} onOpenChange={setLinkDialogOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Insert Link</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <Label>URL</Label>
            <Input
              value={linkUrl}
              onChange={(e) => setLinkUrl(e.target.value)}
              placeholder="https://example.com"
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleLinkInsert();
                }
              }}
            />
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setLinkDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleLinkInsert}>Insert</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Image Dialog */}
      <Dialog open={imageDialogOpen} onOpenChange={setImageDialogOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle>Insert Image</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div>
              <Label>Upload Image</Label>
              <Input
                type="file"
                accept="image/*"
                onChange={handleImageUpload}
                className="mt-1.5 text-sm"
              />
              <p className="text-xs text-muted-foreground mt-1.5">
                Image will be auto-compressed. Max 5MB.
              </p>
            </div>
            <div className="flex items-center gap-2">
              <div className="flex-1 h-px bg-border" />
              <span className="text-xs text-muted-foreground">OR</span>
              <div className="flex-1 h-px bg-border" />
            </div>
            <div>
              <Label>Image URL</Label>
              <Input
                value={imageUrl}
                onChange={(e) => setImageUrl(e.target.value)}
                placeholder="https://example.com/image.jpg"
                className="mt-1.5"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setImageDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleImageInsert}>Insert URL</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
